contracts/AAAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Pausable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";

contract AAAToken is ERC20, ERC20Pausable, AccessControl {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");

    uint256 public immutable maxSupply;
    address public treasury;

    event TreasuryUpdated(address indexed previousTreasury, address indexed newTreasury);

    error ZeroAddress();
    error InvalidSupply();

    constructor(uint256 initialSupply, address initialTreasury, address admin) ERC20("AetherAgentAI", "AAA") {
        if (initialTreasury == address(0) || admin == address(0)) revert ZeroAddress();
        if (initialSupply == 0) revert InvalidSupply();

        maxSupply = initialSupply;
        treasury = initialTreasury;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(TREASURY_ROLE, admin);

        _mint(initialTreasury, initialSupply);
    }

    function setTreasury(address newTreasury) external onlyRole(TREASURY_ROLE) {
        if (newTreasury == address(0)) revert ZeroAddress();
        address previous = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(previous, newTreasury);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function _update(address from, address to, uint256 value) internal override(ERC20, ERC20Pausable) {
        super._update(from, to, value);
    }
}

contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract AgentRegistry is AccessControl, Pausable {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant REPUTATION_ROLE = keccak256("REPUTATION_ROLE");

    struct Agent {
        uint256 id;
        address owner;
        string metadataURI;
        string agentType;
        uint256 reputation;
        uint256 createdAt;
        bool active;
    }

    uint256 public nextAgentId = 1;
    mapping(uint256 => Agent) private agents;

    event AgentRegistered(uint256 indexed agentId, address indexed owner, string metadataURI, string agentType);
    event AgentUpdated(uint256 indexed agentId, string metadataURI);
    event AgentStatusChanged(uint256 indexed agentId, bool active);
    event AgentReputationUpdated(uint256 indexed agentId, uint256 reputation);

    error NotAgentOwner();
    error AgentNotFound();
    error EmptyMetadataURI();

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(REPUTATION_ROLE, admin);
    }

    function registerAgent(string calldata metadataURI, string calldata agentType) external whenNotPaused returns (uint256 agentId) {
        if (bytes(metadataURI).length == 0) revert EmptyMetadataURI();
        agentId = nextAgentId++;
        agents[agentId] = Agent({
            id: agentId,
            owner: msg.sender,
            metadataURI: metadataURI,
            agentType: agentType,
            reputation: 0,
            createdAt: block.timestamp,
            active: true
        });
        emit AgentRegistered(agentId, msg.sender, metadataURI, agentType);
    }

    function updateMetadata(uint256 agentId, string calldata metadataURI) external whenNotPaused {
        Agent storage agent = _agent(agentId);
        if (agent.owner != msg.sender) revert NotAgentOwner();
        if (bytes(metadataURI).length == 0) revert EmptyMetadataURI();
        agent.metadataURI = metadataURI;
        emit AgentUpdated(agentId, metadataURI);
    }

    function setActive(uint256 agentId, bool active) external whenNotPaused {
        Agent storage agent = _agent(agentId);
        if (agent.owner != msg.sender) revert NotAgentOwner();
        agent.active = active;
        emit AgentStatusChanged(agentId, active);
    }

    function updateReputation(uint256 agentId, uint256 reputation) external onlyRole(REPUTATION_ROLE) {
        Agent storage agent = _agent(agentId);
        agent.reputation = reputation;
        emit AgentReputationUpdated(agentId, reputation);
    }

    function getAgent(uint256 agentId) external view returns (Agent memory) {
        return _agent(agentId);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function _agent(uint256 agentId) private view returns (Agent storage agent) {
        agent = agents[agentId];
        if (agent.owner == address(0)) revert AgentNotFound();
    }
}

contracts/RewardDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract RewardDistributor is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant REWARD_FINALIZER_ROLE = keccak256("REWARD_FINALIZER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    IERC20 public immutable aaaToken;
    mapping(address => uint256) public pendingRewards;
    mapping(uint256 => bool) public rewardAllocatedForSubmission;

    event RewardPoolFunded(address indexed funder, uint256 amount);
    event RewardAllocated(uint256 indexed taskId, uint256 indexed submissionId, address indexed recipient, uint256 amount);
    event RewardClaimed(address indexed recipient, uint256 amount);

    error AlreadyAllocated();
    error NoReward();
    error ZeroAddress();
    error ZeroAmount();

    constructor(IERC20 token, address admin) {
        if (address(token) == address(0) || admin == address(0)) revert ZeroAddress();
        aaaToken = token;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REWARD_FINALIZER_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function fundRewardPool(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        aaaToken.safeTransferFrom(msg.sender, address(this), amount);
        emit RewardPoolFunded(msg.sender, amount);
    }

    function allocateReward(uint256 taskId, uint256 submissionId, address recipient, uint256 amount) external onlyRole(REWARD_FINALIZER_ROLE) whenNotPaused {
        if (rewardAllocatedForSubmission[submissionId]) revert AlreadyAllocated();
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        rewardAllocatedForSubmission[submissionId] = true;
        pendingRewards[recipient] += amount;
        emit RewardAllocated(taskId, submissionId, recipient, amount);
    }

    function claim() external nonReentrant whenNotPaused {
        uint256 amount = pendingRewards[msg.sender];
        if (amount == 0) revert NoReward();
        pendingRewards[msg.sender] = 0;
        aaaToken.safeTransfer(msg.sender, amount);
        emit RewardClaimed(msg.sender, amount);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/security/ReentrantClaimer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IRewardDistributor {
    function claim() external;
}

contract ReentrantClaimer {
    IRewardDistributor public immutable distributor;

    constructor(IRewardDistributor target) {
        distributor = target;
    }

    function attack() external {
        distributor.claim();
    }

    receive() external payable {
        distributor.claim();
    }
}

contracts/Staking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract Staking is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    struct StakePosition {
        uint256 amount;
        uint256 updatedAt;
        uint256 unlocksAt;
    }

    IERC20 public immutable aaaToken;
    uint256 public immutable lockPeriod;
    mapping(address => StakePosition) public stakes;

    event Staked(address indexed user, uint256 amount, uint256 unlocksAt);
    event Unstaked(address indexed user, uint256 amount);
    event StakeUpdated(address indexed user, uint256 totalAmount, uint256 unlocksAt);

    error ZeroAmount();
    error StakeLocked(uint256 unlocksAt);
    error InsufficientStake();
    error ZeroAddress();

    constructor(IERC20 token, address admin, uint256 configuredLockPeriod) {
        if (address(token) == address(0) || admin == address(0)) revert ZeroAddress();
        aaaToken = token;
        lockPeriod = configuredLockPeriod;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function stake(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) revert ZeroAmount();
        StakePosition storage position = stakes[msg.sender];
        aaaToken.safeTransferFrom(msg.sender, address(this), amount);
        position.amount += amount;
        position.updatedAt = block.timestamp;
        position.unlocksAt = block.timestamp + lockPeriod;
        emit Staked(msg.sender, amount, position.unlocksAt);
        emit StakeUpdated(msg.sender, position.amount, position.unlocksAt);
    }

    function unstake(uint256 amount) external nonReentrant whenNotPaused {
        StakePosition storage position = stakes[msg.sender];
        if (amount == 0) revert ZeroAmount();
        if (position.amount < amount) revert InsufficientStake();
        if (block.timestamp < position.unlocksAt) revert StakeLocked(position.unlocksAt);
        position.amount -= amount;
        position.updatedAt = block.timestamp;
        aaaToken.safeTransfer(msg.sender, amount);
        emit Unstaked(msg.sender, amount);
        emit StakeUpdated(msg.sender, position.amount, position.unlocksAt);
    }

    function reputationMultiplierBps(address user) external view returns (uint256) {
        uint256 amount = stakes[user].amount;
        if (amount >= 100_000 ether) return 12000;
        if (amount >= 10_000 ether) return 11000;
        if (amount >= 1_000 ether) return 10500;
        return 10000;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/TaskBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract TaskBoard is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant TASK_ADMIN_ROLE = keccak256("TASK_ADMIN_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    enum TaskStatus {
        Open,
        Closed,
        Finalized,
        Cancelled
    }

    struct Task {
        uint256 id;
        address creator;
        string metadataURI;
        string category;
        uint256 rewardAmount;
        uint256 deadline;
        TaskStatus status;
        string validationMethod;
    }

    struct Submission {
        uint256 id;
        uint256 taskId;
        uint256 agentId;
        address submitter;
        string outputURI;
        bytes32 outputHash;
        uint256 timestamp;
    }

    IERC20 public immutable aaaToken;
    uint256 public nextTaskId = 1;
    uint256 public nextSubmissionId = 1;
    mapping(uint256 => Task) private tasks;
    mapping(uint256 => Submission) private submissions;

    event TaskCreated(uint256 indexed taskId, address indexed creator, string metadataURI, uint256 rewardAmount);
    event TaskFunded(uint256 indexed taskId, address indexed funder, uint256 amount);
    event SolutionSubmitted(uint256 indexed submissionId, uint256 indexed taskId, uint256 indexed agentId, address submitter, string outputURI, bytes32 outputHash);
    event TaskStatusChanged(uint256 indexed taskId, TaskStatus status);

    error TaskNotFound();
    error TaskNotOpen();
    error DeadlineExpired();
    error EmptyMetadataURI();
    error InvalidDeadline();

    constructor(IERC20 token, address admin) {
        aaaToken = token;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(TASK_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function createTask(string calldata metadataURI, string calldata category, uint256 rewardAmount, uint256 deadline, string calldata validationMethod) public whenNotPaused nonReentrant returns (uint256 taskId) {
        if (bytes(metadataURI).length == 0) revert EmptyMetadataURI();
        if (deadline <= block.timestamp) revert InvalidDeadline();
        taskId = nextTaskId++;
        tasks[taskId] = Task({
            id: taskId,
            creator: msg.sender,
            metadataURI: metadataURI,
            category: category,
            rewardAmount: 0,
            deadline: deadline,
            status: TaskStatus.Open,
            validationMethod: validationMethod
        });
        emit TaskCreated(taskId, msg.sender, metadataURI, rewardAmount);
        if (rewardAmount > 0) {
            _fundTask(taskId, msg.sender, rewardAmount);
        }
    }

    function adminCreateTask(string calldata metadataURI, string calldata category, uint256 rewardAmount, uint256 deadline, string calldata validationMethod) external onlyRole(TASK_ADMIN_ROLE) returns (uint256) {
        return createTask(metadataURI, category, rewardAmount, deadline, validationMethod);
    }

    function fundTask(uint256 taskId, uint256 amount) public whenNotPaused nonReentrant {
        _fundTask(taskId, msg.sender, amount);
    }

    function _fundTask(uint256 taskId, address funder, uint256 amount) internal {
        Task storage task = _task(taskId);
        if (task.status != TaskStatus.Open) revert TaskNotOpen();
        aaaToken.safeTransferFrom(funder, address(this), amount);
        task.rewardAmount += amount;
        emit TaskFunded(taskId, funder, amount);
    }

    function submitSolution(uint256 taskId, uint256 agentId, string calldata outputURI, bytes32 outputHash) external whenNotPaused returns (uint256 submissionId) {
        Task storage task = _task(taskId);
        if (task.status != TaskStatus.Open) revert TaskNotOpen();
        if (block.timestamp > task.deadline) revert DeadlineExpired();
        if (bytes(outputURI).length == 0) revert EmptyMetadataURI();

        submissionId = nextSubmissionId++;
        submissions[submissionId] = Submission({
            id: submissionId,
            taskId: taskId,
            agentId: agentId,
            submitter: msg.sender,
            outputURI: outputURI,
            outputHash: outputHash,
            timestamp: block.timestamp
        });
        emit SolutionSubmitted(submissionId, taskId, agentId, msg.sender, outputURI, outputHash);
    }

    function setTaskStatus(uint256 taskId, TaskStatus status) external onlyRole(TASK_ADMIN_ROLE) {
        Task storage task = _task(taskId);
        task.status = status;
        emit TaskStatusChanged(taskId, status);
    }

    function getTask(uint256 taskId) external view returns (Task memory) {
        return _task(taskId);
    }

    function getSubmission(uint256 submissionId) external view returns (Submission memory) {
        Submission storage submission = submissions[submissionId];
        if (submission.submitter == address(0)) revert TaskNotFound();
        return submission;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function _task(uint256 taskId) private view returns (Task storage task) {
        task = tasks[taskId];
        if (task.creator == address(0)) revert TaskNotFound();
    }
}

contracts/ValidationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract ValidationRegistry is AccessControl, Pausable {
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant FINALIZER_ROLE = keccak256("FINALIZER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    struct ValidationResult {
        uint256 taskId;
        uint256 submissionId;
        address validator;
        uint256 score;
        uint256 confidence;
        string resultURI;
        uint256 timestamp;
    }

    struct AggregateResult {
        uint256 taskId;
        uint256 submissionId;
        uint256 averageScore;
        uint256 averageConfidence;
        uint256 validatorCount;
        bool finalized;
    }

    mapping(uint256 => ValidationResult[]) private resultsBySubmission;
    mapping(uint256 => mapping(address => bool)) public hasValidated;
    mapping(uint256 => AggregateResult) public finalizedResults;

    event ValidationSubmitted(uint256 indexed taskId, uint256 indexed submissionId, address indexed validator, uint256 score, uint256 confidence, string resultURI);
    event ValidationFinalized(uint256 indexed taskId, uint256 indexed submissionId, uint256 averageScore, uint256 averageConfidence, uint256 validatorCount);

    error InvalidScore();
    error DuplicateValidation();
    error NoValidations();
    error AlreadyFinalized();

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(VALIDATOR_ROLE, admin);
        _grantRole(FINALIZER_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function submitValidation(uint256 taskId, uint256 submissionId, uint256 score, uint256 confidence, string calldata resultURI) external onlyRole(VALIDATOR_ROLE) whenNotPaused {
        if (score > 10000 || confidence > 10000) revert InvalidScore();
        if (hasValidated[submissionId][msg.sender]) revert DuplicateValidation();
        hasValidated[submissionId][msg.sender] = true;
        resultsBySubmission[submissionId].push(ValidationResult({
            taskId: taskId,
            submissionId: submissionId,
            validator: msg.sender,
            score: score,
            confidence: confidence,
            resultURI: resultURI,
            timestamp: block.timestamp
        }));
        emit ValidationSubmitted(taskId, submissionId, msg.sender, score, confidence, resultURI);
    }

    function finalizeValidation(uint256 submissionId) external onlyRole(FINALIZER_ROLE) whenNotPaused returns (AggregateResult memory aggregate) {
        if (finalizedResults[submissionId].finalized) revert AlreadyFinalized();
        ValidationResult[] storage results = resultsBySubmission[submissionId];
        if (results.length == 0) revert NoValidations();

        uint256 scoreSum;
        uint256 confidenceSum;
        for (uint256 i = 0; i < results.length; i++) {
            scoreSum += results[i].score;
            confidenceSum += results[i].confidence;
        }

        aggregate = AggregateResult({
            taskId: results[0].taskId,
            submissionId: submissionId,
            averageScore: scoreSum / results.length,
            averageConfidence: confidenceSum / results.length,
            validatorCount: results.length,
            finalized: true
        });
        finalizedResults[submissionId] = aggregate;
        emit ValidationFinalized(aggregate.taskId, submissionId, aggregate.averageScore, aggregate.averageConfidence, aggregate.validatorCount);
    }

    function getValidationCount(uint256 submissionId) external view returns (uint256) {
        return resultsBySubmission[submissionId].length;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

